parameters.parameters/uri:
@if(
  not(empty(variables('strRequestOutput'))),
  if(
    contains(
      string(items('Each_Request')?['Uri']),
      '_replace_with_previous_output_'
    ),
    replace(
      items('Each_Request')?['Uri'],
      '_replace_with_previous_output_',
      variables('strRequestOutput')
    ),
    items('Each_Request')?['Uri']
  ),
  items('Each_Request')?['Uri']
)

parameters.parameters/headers:
@if(
  not(empty(variables('strRequestOutput'))),
  if(
    contains(
      string(items('Each_Request')?['Headers']),
      '_replace_with_previous_output_'
    ),
    json(
      replace(
        string(items('Each_Request')?['Headers']),
        '_replace_with_previous_output_',
        variables('strRequestOutput')
      )
    ),
    items('Each_Request')?['Headers']
  ),
  items('Each_Request')?['Headers']
)

parameters.parameters/body:
@if(
  not(empty(variables('strRequestOutput'))),
  if(
    contains(
      string(items('Each_Request')?['Body']),
      '_replace_with_previous_output_'
    ),
    json(
      replace(
        string(items('Each_Request')?['Body']),
        '_replace_with_previous_output_',
        variables('strRequestOutput')
      )
    ),
    items('Each_Request')?['Body']
  ),
  items('Each_Request')?['Body']
)

inputs.value:
@if(
    empty(
        string(
            items('Each_Request')?['Output']
        )
    ),
    '',
    if(
      empty(string(body('SharePoint_Request')?['d']?['results'])),
      string(
          body('SharePoint_Request')?['d']?[
              items('Each_Request')?['Output']
          ]
      ),
      string(
          first(body('SharePoint_Request')?['d']?['results'])?[
              items('Each_Request')?['Output']
          ]
      )
    )
)
